export const CAREER_COURSE_CATALOG = Object.freeze(Object.fromEntries(
    Object.entries(catalog).map(([career, levels]) => [career, Object.freeze(levels.flatMap((courses, levelIndex) =>
        courses.map(([title, scope], courseIndex) => Object.freeze({
            career,
            qualificationLevel: levelIndex + 1,
            courseIndex: courseIndex + 1,
            title,
            teachingScope: scope,
        }))))]),
));

export function courseCatalog(careers = Object.keys(CAREER_COURSE_CATALOG)) {
    return careers.flatMap((career) => CAREER_COURSE_CATALOG[career] ?? []);
}
